-- =====================================================================
-- Lib: CVH (cdnvideohub.com player API) — URL resolution only.
-- Extracted from ru/yummyanime.lua (voiceLabel, cvhVideoUrl,
-- cvhSourceFrom).
-- Loaded via require_lib("cvh"). No dependencies on other libs.
--
-- The playlist/detail part (shikimori_id -> plapi.cdnvideohub.com) stays
-- in the plugin: it shares the session caches of the plugin and its
-- http_get calls. Here only the per-video URL and its response parsing:
-- the caller batches the GETs (batchCvh) and hands the response back.
-- =====================================================================
local version = "1.0.0"

local M = {}

-- Same player API base as CVH_API in the plugin (that one serves the
-- playlist, this one the single video).
local CVH_API = "https://plapi.cdnvideohub.com/api/v1/player/sv"

-- The voice label of a playlist element — the quality caption of the
-- source and the key the player remembers the choice by, it must be
-- distinctive.
local function voiceLabel(item)
    local studio = type(item.voiceStudio) == "string" and item.voiceStudio or ""
    local vtype  = type(item.voiceType) == "string" and item.voiceType or ""
    local label
    if studio ~= "" and vtype ~= "" then
        label = studio .. " (" .. vtype .. ")"
    elseif studio ~= "" then
        label = studio
    elseif vtype ~= "" then
        label = vtype
    else
        label = "vk" .. tostring(item.vkId)
    end
    return string_clean(label)
end

-- nil vkId (a playlist without an identifier) → nil: batchCvh skips the
-- request, pages[nil] then returns nil and no source is produced.
function M.videoUrl(vkId)
    if vkId == nil then return nil end
    return CVH_API .. "/video/" .. vkId
end

-- A CVH video response → a source. No stream headers are set: the signed
-- okcdn segments (.../sig/<signature>/...) answer 400 when the request
-- carries Referer or Origin. Verified: without them a segment answers
-- 200, with them 400 for any User-Agent. Referer/Origin are only needed
-- for the plugin's own API requests (CVH_HDR there).
-- Returns { url, quality } or nil.
function M.sourceFrom(item, r)
    if type(r) ~= "table" or not r.success then return nil end
    local data = json_parse(r.body)
    local hls = data and data.sources and data.sources.hlsUrl
    if type(hls) ~= "string" or hls == "" then return nil end
    return { url = hls, quality = voiceLabel(item) }
end

return M
end

__LOADERS["fetch"] = function(...)
-- =====================================================================
-- Lib: session-cached page fetch. The engine calls getBookTitle /
-- getBookCoverImageUrl / getBookDescription / getBookGenres /
-- getBookStatus / getBookLastUpdate in parallel, each doing its own
-- http_get(bookUrl) — this module keeps one request per URL.
-- Loaded via require_lib("fetch"). No dependencies on other libs.
--
-- Same contract as the inline fetchPage copies (guide:643):
--   * cache lives for the session only, never for getChapterListHash —
--     that one must always use a direct http_get;
--   * only successful responses are cached, a failed call returns nil
--     and the next call retries;
--   * the cache key is the URL. A non-empty `config` that changes the
--     response body (headers, charset, ...) becomes part of the key, so
--     two configs never share a body.
-- =====================================================================
local version = "1.0.0"

local M = {}

local cache = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

-- Order-independent encoding of a config table, so {a=1,b=2} and {b=2,a=1}
-- share one cache entry. Cycles are not possible here: http_get configs are
-- plain string/number/bool values and one level of headers table.
local function encode(value)
    local t = type(value)
    if t == "table" then
        local keys = {}
        for k in pairs(value) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
        local parts = {}
        for _, k in ipairs(keys) do
            parts[#parts + 1] = tostring(k) .. "=" .. encode(value[k])
        end
        return "{" .. table.concat(parts, ";") .. "}"
    end
    return tostring(value)
end

local function keyOf(url, config)
    if type(config) ~= "table" then return url end
    local keys = {}
    for k in pairs(config) do keys[#keys + 1] = k end
    if #keys == 0 then return url end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    local parts = {}
    for _, k in ipairs(keys) do
        parts[#parts + 1] = tostring(k) .. "=" .. encode(config[k])
    end
    return url .. "\0" .. table.concat(parts, ";")
end

-- GET `url` (optional http_get `config`) -> response body or nil.
-- ponytail: no TTL — the plugin session is short-lived and every copy in
-- the repo caches for the whole session (only mtl/wtrlab.lua adds a TTL);
-- add one when a caller actually needs staleness control.
function M.page(url, config)
    if type(url) ~= "string" or url == "" then return nil end
    local key = keyOf(url, config)
    local cached = cache[key]
    if cached ~= nil then return cached end
    local r = http_get(url, config)
    if type(r) ~= "table" or not r.success then
        logErr("fetch: GET failed (HTTP " .. tostring(r and r.code) .. ") " .. url)
        return nil
    end
    cache[key] = r.body
    return r.body
end

-- Drop the whole session cache, or every entry of one URL when given
-- (all config variants of that URL).
function M.clear(url)
    if url == nil then
        cache = {}
        return
    end
    local prefix = url .. "\0"
    for key in pairs(cache) do
        if key == url or key:sub(1, #prefix) == prefix then cache[key] = nil end
    end
end

return M
end

__LOADERS["gdriveplayer"] = function(...)
-- =====================================================================
-- Lib: gdriveplayer resolver — embed2.php serves a page whose inline
--      script body is atob()'ed and XOR-encrypted with the key from
--      `var k="..."`; the decrypted JS carries a relative HLS path
--      HLS="hlsplaylist.php?s=…&idhls=….m3u8" — a media playlist with
--      direct segments on a third-party CDN.
-- From one copy: id/animexin.lua:568-617 (resolveGdriveplayer + bxor8).
-- Loaded via require_lib("gdriveplayer"). No dependencies on other libs.
--
-- Pure decode: the caller does the batch GET (Referer = embed origin);
-- logging stays with the caller. base64_decode is engine API («Тяжёлые
-- операции»); the XOR loop stays in Lua — it runs over one short script.
-- =====================================================================
local version = "1.0.0"

local M = {}

-- XOR of two bytes, bit by bit (sandbox is Lua 5.1 — no bitwise ops).
local function bxor8(a, b)
    local r, p = 0, 1
    for _ = 1, 8 do
        local ab, bb = a % 2, b % 2
        if ab ~= bb then r = r + p end
        a = math.floor(a / 2)
        b = math.floor(b / 2)
        p = p * 2
    end
    return r
end

-- body — the embed2.php page; origin — "scheme://host/" of the embed
-- (used to absolutise a relative HLS path).
-- Returns a list of { url, mime = "hls" } or nil + reason:
-- "no key/atob in embed" | "atob did not decode" | "HLS= not found after decrypt".
function M.decode(body, origin)
    if type(body) ~= "string" then return nil, "no key/atob in embed" end
    local key = body:match('var k="([^"]+)"')
    local blob = body:match('atob%("([^"]+)"%)')
    if not key or not blob or #key == 0 then
        return nil, "no key/atob in embed"
    end
    local raw = base64_decode(blob)
    if type(raw) ~= "string" or raw == "" then
        return nil, "atob did not decode"
    end
    local chars = {}
    local klen = #key
    for i = 1, #raw do
        chars[i] = string.char(bxor8(raw:byte(i), key:byte((i - 1) % klen + 1)))
    end
    local decoded = table.concat(chars)
    local hls = decoded:match('HLS="([^"]+)"')
    if not hls then return nil, "HLS= not found after decrypt" end
    hls = hls:gsub("\\/", "/")
    if hls:sub(1, 2) == "//" then
        hls = "https:" .. hls
    elseif hls:sub(1, 1) == "/" then
        hls = origin .. hls
    else
        hls = origin .. "/" .. hls
    end
    return { { url = hls, mime = "hls" } }
end

return M
end

__LOADERS["hls"] = function(...)
-- =====================================================================
-- Lib: stream helpers for videohost extractors: pickStream (generic
--      m3u8/mp4 scan) + hasMediaExt (mime typing of extension-less URLs).
-- Loaded via require_lib("hls"); uses require_lib("urls").
-- =====================================================================
local version = "1.0.0"

local urls = require_lib("urls")

local M = {}

-- =====================================================================
-- Generic stream scan
-- =====================================================================

function M.pickStream(t, embedUrl)
    -- 1) absolute URL
    local hls = t:match([=[(https?://[^"'%s\<>]+%.m3u8[^"'%s\<>]*)]=])
    if hls then return hls, "hls" end

    -- 2) quoted, relative or protocol-relative
    for _, q in ipairs({ '"', "'" }) do
        for s in t:gmatch(q .. "([^" .. q .. "\r\n]+)" .. q) do
            if #s < 600 and not s:find("%s") and s:lower():find(".m3u8", 1, true) then
                return urls.resolve(s, embedUrl), "hls"
            end
        end
    end

    -- 3) direct mp4
    local mp4 = t:match([=[(https?://[^"'%s\<>]+%.mp4[^"'%s\<>]*)]=])
    if mp4 then return mp4, "mp4" end
    for _, q in ipairs({ '"', "'" }) do
        for s in t:gmatch(q .. "(//[^" .. q .. "\r\n]+)" .. q) do
            if #s < 600 and not s:find("%s") and s:lower():find(".mp4", 1, true) then
                return urls.resolve(s, embedUrl), "mp4"
            end
        end
    end
    return nil, nil
end

-- =====================================================================
-- Media extension check
-- =====================================================================

-- Does the URL path (before "?" / "#") end with a media extension?
-- Without it media3 types the stream as progressive and fails on an HLS
-- body (rationale: ar/anime4up.lua:328). Union of the three plugin copies
-- (ar/anime4up.lua:330, ar/animephoenix.lua:45, ar/witanime.lua:1958):
-- .mkv comes from animephoenix and is progressive too, so it must not be
-- typed as "hls".
function M.hasMediaExt(u)
    local base = u:match("^[^%?#]*") or u
    return base:match("%.m3u8$") ~= nil
        or base:match("%.mp4$") ~= nil
        or base:match("%.mkv$") ~= nil
end

return M
end

__LOADERS["kodik"] = function(...)
-- =====================================================================
-- Lib: Kodik — embed page (urlParams/d_sign) -> POST kodikplayer.com/ftor
--      -> quality list of direct links.
-- Extracted from ru/yummyanime.lua (kodikDecode + resolveKodik), the port
-- of the Kodik player flow.
-- Loaded via require_lib("kodik"); uses require_lib("text") (rot18) and
-- the engine base64_decode. No other lib dependencies.
--
-- The embed HTML is already in hand (the caller loads it with its batch),
-- only /ftor is a POST done here. The body is form-urlencoded and stays
-- hand-assembled on purpose — json_encode would send the wrong shape.
-- =====================================================================
local version = "1.0.0"

local TEXT = require_lib("text")

local M = {}

-- src in the /ftor answer is either an absolute URL or ROT-18 over
-- letters + base64 (the engine base64_decode gets a URL string, no binary
-- is needed).
local function kodikDecode(src)
    if src:find("//", 1, true) then return src end
    local url = base64_decode(TEXT.rot18(src))
    if not url or url == "" then return nil end
    if url:sub(1, 2) == "//" then return "https:" .. url end
    return url
end

-- page — the shared http_get_batch response for this iframe (see
-- batchPlayers in the plugin): the Kodik/Alloha embeds are loaded by one
-- batch, without their own headers.
-- Returns a list of { url, quality } or nil.
function M.resolve(iframeUrl, dubbing, page)
    if type(page) ~= "table" or not page.success then
        log_error("kodik: iframe " .. tostring(page and page.code))
        return nil
    end
    local url = iframeUrl
    if url:sub(1, 2) == "//" then url = "https:" .. url end
    local html = page.body
    -- urlParams is a JSON with the d_sign/pd_sign/ref_sign signatures;
    -- without them /ftor answers 500
    local raw = html:match("urlParams%s*=%s*'([^']+)'")
        or html:match('urlParams%s*=%s*"([^"]+)"')
    local params = raw and json_parse(raw) or nil
    if type(params) ~= "table" or type(params.d_sign) ~= "string" or params.d_sign == "" then
        log_error("kodik: urlParams not found")
        return nil
    end
    local vtype = html:match("vInfo%.type%s*=%s*'([^']+)'")
        or html:match('var%s+type%s*=%s*"([^"]+)"')
    local vhash = html:match("vInfo%.hash%s*=%s*'([^']+)'")
    local vid   = html:match('videoId%s*=%s*"([^"]+)"')
        or html:match("vInfo%.id%s*=%s*'([^']+)'")
    if not vtype or not vhash or not vid then
        -- fallback: the iframe path segments are host/type/id/hash
        local seg = {}
        for part in url:gsub("[?#].*$", ""):gmatch("[^/]+") do seg[#seg + 1] = part end
        vtype = vtype or seg[2]
        vid   = vid   or seg[3]
        vhash = vhash or seg[4]
    end
    if not vtype or not vid or not vhash then
        log_error("kodik: type/id/hash not found")
        return nil
    end
    local function field(v)
        return url_encode(type(v) == "string" and v or "")
    end
    -- ponytail: ref/ref_sign are not sent — the server signs them for the
    -- iframe request Referer, while the engine always sends its own
    -- Referer, so the signature mismatches and /ftor answers 500; without
    -- these fields both cases answer 200
    local body = table.concat({
        "d=",        field(params.d),
        "&d_sign=",  field(params.d_sign),
        "&pd=",      field(params.pd),
        "&pd_sign=", field(params.pd_sign),
        "&type=",    url_encode(vtype),
        "&id=",      url_encode(vid),
        "&hash=",    url_encode(vhash),
        "&bad_user=false&cdn_is_working=true",
    })
    local pr = http_post("https://kodikplayer.com/ftor", body)
    if not pr.success then
        log_error("kodik: /ftor " .. tostring(pr.code))
        return nil
    end
    local data = json_parse(pr.body)
    local links = data and data.links
    if type(links) ~= "table" then return nil end
    -- links keys are the qualities as strings ("240".."720"), highest first
    local qs = {}
    for k in pairs(links) do
        if type(k) == "string" and k:match("^%d+$") then qs[#qs + 1] = k end
    end
    table.sort(qs, function(a, b) return tonumber(a) > tonumber(b) end)
